import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.DVCfY5-a.js";const k=JSON.parse('{"title":"Pin Newton and observe SO-101","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/newton-motion","contentType":"tutorial","prev":{"text":"Capture and inspect a Recording","link":"/en/tutorials/recording"},"next":{"text":"Watch securely, resubscribe and deploy WSS","link":"/en/tutorials/secure-motion"}},"headers":[],"relativePath":"en/tutorials/newton-motion.md","filePath":"en/tutorials/newton-motion.md"}'),n={name:"en/tutorials/newton-motion.md"};function o(r,e,l,h,d,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="pin-newton-and-observe-so-101" tabindex="-1">Pin Newton and observe SO-101 <a class="header-anchor" href="#pin-newton-and-observe-so-101" aria-label="Permalink to &quot;Pin Newton and observe SO-101&quot;">​</a></h1><p>Continue from <a href="./recording">Recording</a>. This chapter uses one SO-101, a vial, a four-hole rack and a mat. Newton/MJWarp solves on Linux or WSL GPU. Two Lab Viewers observe the same Session. Ordinary Node/Web startup needs no Python physics dependencies.</p><h2 id="pin-inputs-and-the-environment" tabindex="-1">Pin inputs and the environment <a class="header-anchor" href="#pin-inputs-and-the-environment" aria-label="Permalink to &quot;Pin inputs and the environment&quot;">​</a></h2><p>Use CPython 3.12.3, Newton 1.6.0rc1, Warp 1.17.0, MuJoCo/MJWarp 3.12.0 and websockets 15.0.1. The probe and Recording source header record actual versions. This adapter uses Newton directly and starts no Isaac Sim Kit. The header records Isaac Lab when installed, or <code>null</code> when absent.</p><p>You can use an existing environment read-only. Keep installations and outputs out of existing user projects and environments. Create an owned environment when installation is needed. Run these commands from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.12.3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/newton-env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/newton-env/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/newton-motion/requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PYTHONDONTWRITEBYTECODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> .scratch/newton-env/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/newton-motion/prepare.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/newton-scene</span></span></code></pre></div><p><code>prepare.py</code> checks the ten repository-owned GLBs and recovers the exact physics archive inside the base GLB through the production loader. The archive retains 13 original maker STLs, six follower and five moving derived collision files, licenses and provenance. This step uses no network or new collision generation. Use a new output directory and preserve a failed directory for diagnosis.</p><p>Assets come from <a href="https://github.com/TheRobotStudio/SO-ARM100/tree/a758567c3978dfeefe282ede0500085a48fe8f78/Simulation/SO101" target="_blank" rel="noreferrer">TheRobotStudio/SO-ARM100</a>. The checked-in descriptions and meshes use its Apache-2.0 publication. Lab World authors the vial, rack and mat. See <a href="https://github.com/CaiZongyuan/labworld/blob/9e0f1040608f5c40d7e7b33f9c0b099b32ed88b5/tools/newton-motion/scene/NOTICE.md" target="_blank" rel="noreferrer">NOTICE</a> and <a href="https://github.com/CaiZongyuan/labworld/blob/9e0f1040608f5c40d7e7b33f9c0b099b32ed88b5/tools/newton-motion/scene/LICENSE" target="_blank" rel="noreferrer">LICENSE</a> for sources and credits. This chapter distributes no uncleared NVIDIA conversion and claims no equivalent dynamics.</p><h2 id="check-the-actual-gpu-first" tabindex="-1">Check the actual GPU first <a class="header-anchor" href="#check-the-actual-gpu-first" aria-label="Permalink to &quot;Check the actual GPU first&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PYTHONDONTWRITEBYTECODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> .scratch/newton-env/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/newton-motion/probe.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --base-glb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/newton-scene/base.glb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/newton-probe-cache</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --steps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 120</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/newton-probe.json</span></span></code></pre></div><p>The probe must initialize <code>cuda:0</code>, load the fixed scene and execute 120 physics steps. It records dependencies, device, setup, solver, control and batch readback windows. It proves no browser, Recording or grasp acceptance. Diagnose the scene, initial state and drives before changing a failed physical baseline. Keep the contact criteria unchanged.</p><p>The base GLB retains a fixed physics ZIP. The loader checks trusted whole-file and archive hashes before allowlisted extraction. Matching extras alone cannot authorize a scene. Missing, transformed or changed archives fail before solver import.</p><h2 id="install-and-start" tabindex="-1">Install and Start <a class="header-anchor" href="#install-and-start" aria-label="Permalink to &quot;Install and Start&quot;">​</a></h2><p>Follow <a href="./../getting-started/quickstart">Quickstart</a> to create Node data and log in. Configure the fixed source before startup:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAB_WORD_NEWTON_SESSION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAB_WORD_NEWTON_PYTHON=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.scratch/newton-env/bin/python&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAB_WORD_NEWTON_SCENE_DIRECTORY=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.scratch/newton-scene&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">dev</span></span></code></pre></div><p>The server owns temporary caches, process ledgers and a shared compilation cache. It manages one local GPU source at a time. Preparation takes no Publisher lease. After readiness, it obtains the lease, epoch and Recording credentials. Existing heartbeat and durable-capture deadlines remain unchanged. You can Stop preparation; parent exit or stdin closure ends its source.</p><p>Create a Lab. Import the ten generated GLBs into the Asset Library. Select <strong>Install SO-101 Newton scene</strong> in the Session panel. An Agent key with <code>lab:full</code> can also perform the complete installation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/newton-motion/install_scene.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --lab</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lab-uui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/newton-scene</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/newton-install.json</span></span></code></pre></div><p>Provide the key through <code>LAB_WORD_API_KEY</code>. Keep it out of commands and ledgers. The script creates persistent Assets and a Scene Installation. On failure, retain completed assets and the ledger for inspection. It removes no other assets.</p><p>New installations use <code>so101-vial@2</code>. Start holds the initial pose and waits for <a href="./robot-controls">formal robot actions</a>. Open another authenticated browser for the same Lab. Both viewers should show the same solved link and vial poses. Cameras and selection remain independent. Existing <code>so101-vial@1</code> installations keep the fixed demo trajectory. Enable robot controls explicitly in the Session panel while idle.</p><h2 id="compare-three-physical-moments" tabindex="-1">Compare three physical moments <a class="header-anchor" href="#compare-three-physical-moments" aria-label="Permalink to &quot;Compare three physical moments&quot;">​</a></h2><p>For the old fixed demo, compare stationary, physically lifted and released moments using independent source and Viewer world transforms. Set <code>LAB_WORD_NEWTON_EVIDENCE_DIRECTORY</code> to an owned verification directory before startup when needed. The source retains at most 900 raw sampling witnesses with actual contact and state. This explicit measurement mode adds contact and velocity readback; its cost is recorded separately. A stage name describes a target; it does not prove success.</p><p>The fixed demo keeps the original initial state and vial-local cap centre <code>z=0.094 m</code>. It enters horizontally at cap height along the grip axis. Targets close to <code>0.4 rad</code>, then <code>0.3 rad</code> during lift and <code>0.2 rad</code> during held/lower. The internal lift goal is <code>0.012 m</code>. Real GPU evidence reached about 9.00 mm rise and passed ten consecutive bilateral control samples above 6 mm. After release, 15 consecutive samples met the seated criteria from step 3448 through 3560. The last sample at step 4320 did not meet those criteria; this validates the measured window, not permanent seating. The trail also records brief shoulder/lower-arm contact at step 968, so it does not establish clearance over the entire path. Viewer and Recording acceptance remains separate.</p><p>Native coordinates use right-handed Z-up, metres and XYZW. Wire coordinates use right-handed Y-up, metres and XYZW. Conversion maps native <code>(x,y,z)</code> to <code>(x,z,-y)</code>. GLB centering remains child-local; the fixed <code>body_to_visual</code> correction is composed once. Links share one robot Entity with distinct visual targets. The vial, rack and mat retain independent identities.</p><p>Physics runs at 240 Hz; control and reliable selected sampling run at 30 Hz. Each readback batches fixed body/joint keys. Sampling, encoding and writers have separate ownership. Start the same initial conditions with HTTP <code>live_rate_hz: 15</code> and <code>30</code>. Compare outcomes at identical physics steps. The 15 Hz setting selects fewer live frames; reliable sampling and GPU readback stay at 30 Hz. Correlated lifecycle boundaries always send after exact durable ACKs.</p><p>Pause freezes physics and simulation time. Resume continues that state. Reset creates a new Session/Recording from the original snapshot. A later ordinary Start uses the latest saved layout. This fixed profile requires unit visual scale and rejects unsupported scaling.</p><h2 id="inspect-recording-and-one-failure" tabindex="-1">Inspect Recording and one failure <a class="header-anchor" href="#inspect-recording-and-one-failure" aria-label="Permalink to &quot;Inspect Recording and one failure&quot;">​</a></h2><p>Follow <a href="./recording">Recording inspection</a> to check integrity, source sequences and events after Stop. The header must identify <code>newton</code> and actual software, GPU, driver, profile and live rate. Formal Recording file references retain the archive and every GLB.</p><p>Read a retained dependency through:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/lab/labs/{lab_id}/recordings/{recording_id}/resources/{file_id}</span></span></code></pre></div><p>Find <code>file_id</code> in the manifest&#39;s <code>snapshot.world.assets[*].representation</code>. The response contains verified original bytes. Recording can supply them after the current Asset or local cache disappears. Foreign files, deleted Recordings and unknown files return controlled 404. The opened stream retains custody during reading; cancellation releases it.</p><p>Substitute a same-named GLB with another hash in the installation mapping. Installation must return <code>lab.newton_representation_mismatch</code>. A Publisher with a wrong HELLO <code>scene_hash</code> cannot inject motion. Restore the fixed files and explicitly Start a new Session. Sources do not reconnect or replay old experiments automatically.</p><p>After Stop, verify <code>cleaned</code> process ledgers and removed extraction directories. Shared Warp compilation caches and explicit witnesses can remain with their owner and purpose recorded. Actual public and cross-host acceptance requires the later deployment environment; loopback results cannot replace it.</p><p>Implementation: <a href="https://github.com/CaiZongyuan/labworld/blob/9e0f1040608f5c40d7e7b33f9c0b099b32ed88b5/tools/newton-motion/prepare.py" target="_blank" rel="noreferrer">scene generation</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/9e0f1040608f5c40d7e7b33f9c0b099b32ed88b5/tools/newton-motion/scene_loader.py" target="_blank" rel="noreferrer">trusted loading</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/9e0f1040608f5c40d7e7b33f9c0b099b32ed88b5/tools/newton-motion/physics.py" target="_blank" rel="noreferrer">Newton sampling</a>, and <a href="https://github.com/CaiZongyuan/labworld/blob/9e0f1040608f5c40d7e7b33f9c0b099b32ed88b5/tools/newton-motion/publisher.py" target="_blank" rel="noreferrer">independent writer</a>.</p><hr><p>Source version：<code>9e0f1040608f</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/9e0f1040608f5c40d7e7b33f9c0b099b32ed88b5/docs/tutorials/newton-motion.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,36)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
